// draw_frontend_widget @ 0x401130 (thiscall)

#include "border_manager.h"
#include "font_system.h"
#include "frontend_widget.h"
#include "game_root.h"
#include "runtime_config.h"


int OSDPrintUV(
    int texture_id,
    float x,
    float y,
    float base_width,
    float base_height,
    int flags,
    tColour* color,
    float u0,
    float v0,
    float u1,
    float v1,
    int blend_mode,
    float rotation);

void cRBorder::Draw()
{
    tColour white;
    tColour slider_color;
    tColour reserved_color_0; // native prologue object; alpha is initialized below
    tColour reserved_color_1; // native constructor-only prologue object

    white.noop_this_constructor();
    slider_color.noop_this_constructor();
    reserved_color_1.noop_this_constructor();
    reserved_color_0.noop_this_constructor();

    if (g_render_queue_active == 0)
        return;

    unsigned int flags = widget_flags;
    if ((flags & FRONTEND_WIDGET_FLAG_HIDDEN) != 0)
        return;

    int blend_mode;
    if ((g_runtime_config.render_flags & 0x80) == 0) {
        white.a = 1.0f;
        reserved_color_0.a = 1.0f;
        blend_mode = 0;
    } else {
        blend_mode = 3;
    }

    float base_width = layout_width;
    float base_height = layout_height;

    if ((flags & FRONTEND_WIDGET_FLAG_SLIDER) != 0) {
        slider_color = current_text_color;
        tColour* color = &slider_color;
        if (slider_position_current > 0.0f) {
            OSDPrintUV(
                37,
                texture_hit_x + base_width * 0.5f - 128.0f,
                texture_hit_y + 50.0f,
                slider_position_current * 256.0f,
                32.0f,
                0x1000000,
                color,
                0.0f,
                0.0f,
                slider_position_current,
                1.0f,
                blend_mode,
                0);
        }
        if (slider_position_current < 1.0f) {
            OSDPrintUV(
                36,
                texture_hit_x + base_width * 0.5f - 128.0f + slider_position_current * 256.0f,
                texture_hit_y + 50.0f,
                (1.0f - slider_position_current) * 256.0f,
                32.0f,
                0x1000000,
                color,
                slider_position_current,
                0.0f,
                1.0f,
                1.0f,
                blend_mode,
                0);
        }
    }

    if (sprite_extend_enabled != 0) {
        float wobble = 0.0f;
        if (g_game->border_manager.delayed_widget_active != 0
            && this == g_game->border_manager.delayed_widget) {
            wobble = Sin(
                g_game->border_manager.delayed_widget_progress
                * 3.1415927f) * 3.0f;
            if (sprite_wobble_positive == 0)
                wobble = wobble * -1.0f;
        }

        float pad = border_edge * 0.5f;
        if ((widget_flags & FRONTEND_WIDGET_FLAG_HIGHLIGHTED) != 0) {
            OSDPrintUV(
                sprite_hot_texture_id,
                texture_hit_x + wobble - pad,
                texture_hit_y - pad,
                texture_hit_width + border_edge,
                texture_hit_height + border_edge,
                0x1000000,
                &current_text_color,
                0.0f,
                0.0f,
                1.0f,
                1.0f,
                texture_layer,
                0);
        } else {
            OSDPrintUV(
                texture_id,
                texture_hit_x + wobble - pad,
                texture_hit_y - pad,
                texture_hit_width + border_edge,
                texture_hit_height + border_edge,
                0x1000000,
                &current_text_color,
                0.0f,
                0.0f,
                1.0f,
                1.0f,
                texture_layer,
                0);
        }
        return;
    }

    if ((widget_flags & FRONTEND_WIDGET_FLAG_SPRITE_MODE) != 0) {
        float sprite_edge = border_edge;
        float pad = border_edge * 0.5f;
        OSDPrintUV(
            texture_id,
            texture_hit_x - pad,
            texture_hit_y - pad,
            sprite_edge + texture_hit_width,
            texture_hit_height + border_edge,
            0x1000000,
            &current_text_color,
            0.0f,
            0.0f,
            1.0f,
            1.0f,
            texture_layer,
            0);

        if (sprite_shadow_offset > 0.0f) {
            tColour shadow_color;
            float shadow_pad = border_edge * 0.5f;
            OSDPrintUV(
                texture_id,
                texture_hit_x + sprite_shadow_offset - shadow_pad,
                texture_hit_y + sprite_shadow_offset - shadow_pad,
                border_edge + texture_hit_width,
                texture_hit_height + border_edge,
                0x1000000,
                shadow_color.Set(0.0f, 0.0f, 0.0f, 0.89999998f),
                0.0f,
                0.0f,
                1.0f,
                1.0f,
                2,
                0);
        }
    }

    if ((widget_flags & FRONTEND_WIDGET_FLAG_FRAMELESS) != 0)
        return;

    float x, y, width, height, edge, u0, u1;
    if (render_inset_dynamic != 0) {
        edge = 4.0f;
        u0 = 0.1f;
        u1 = 0.89999998f;
        x = texture_hit_x + 4.0f;
        y = texture_hit_y + 3.0f;
        width = base_width - 8.0f;
        height = base_height - 6.0f;
    } else if (current_padding < render_inset_base) {
        float delta = render_inset_base - current_padding;
        render_inset_delta = delta;
        edge = render_inset_base;
        x = texture_hit_x + delta;
        y = texture_hit_y + delta;
        width = base_width - (delta + delta);
        height = base_height - (delta + delta);
        u0 = edge * 0.0078125f;
        u1 = 1.0f - u0;
    } else {
        x = texture_hit_x;
        y = texture_hit_y;
        width = base_width;
        height = base_height;
        edge = current_padding;
        u0 = 0.2f;
        u1 = 0.80000001f;
    }

    float top = y - edge;
    float left = x - edge;

    OSDPrintUV(border_texture_id, left, top, edge, edge, 0x1000000, &current_fill_color, 0.0f, 0.0f, u0, u0, blend_mode, 0);
    OSDPrintUV(border_texture_id, x, top, width, edge, 0x1000000, &current_fill_color, u0, 0.0f, u1, u0, blend_mode, 0);
    float right = x + width;
    OSDPrintUV(border_texture_id, right, top, edge, edge, 0x1000000, &current_fill_color, u1, 0.0f, 1.0f, u0, blend_mode, 0);
    OSDPrintUV(border_texture_id, left, y, edge, height, 0x1000000, &current_fill_color, 0.0f, u0, u0, u1, blend_mode, 0);
    OSDPrintUV(border_texture_id, x, y, width, height, 0x1000000, &current_fill_color, u0, u0, u1, u1, blend_mode, 0);
    OSDPrintUV(border_texture_id, right, y, edge, height, 0x1000000, &current_fill_color, u1, u0, 1.0f, u1, blend_mode, 0);
    float bottom = y + height;
    OSDPrintUV(border_texture_id, left, bottom, edge, edge, 0x1000000, &current_fill_color, 0.0f, u1, u0, 1.0f, blend_mode, 0);
    OSDPrintUV(border_texture_id, x, bottom, width, edge, 0x1000000, &current_fill_color, u0, u1, u1, 1.0f, blend_mode, 0);
    OSDPrintUV(border_texture_id, right, bottom, edge, edge, 0x1000000, &current_fill_color, u1, u1, 1.0f, 1.0f, blend_mode, 0);

    if (g_game->border_manager.delayed_widget_active != 0
        && this == g_game->border_manager.delayed_widget) {
        tColour glow_color;
        glow_color.noop_this_constructor();
        white.White();
        glow_color.store_color4f(
            white.r,
            white.g,
            white.b,
            1.0f - g_game->border_manager.delayed_widget_progress);
        float glow_edge =
            (g_game->border_manager.delayed_widget_progress
                * 0.69999999f
             + 1.0f) * edge;
        OSDPrintUV(99, x - glow_edge, y - glow_edge, glow_edge, glow_edge, 0x1000000, &glow_color, 0.0f, 0.0f, u0, u0, 3, 0);
        OSDPrintUV(99, x, y - glow_edge, width, glow_edge, 0x1000000, &glow_color, u0, 0.0f, u1, u0, 3, 0);
        OSDPrintUV(99, right, y - glow_edge, glow_edge, glow_edge, 0x1000000, &glow_color, u1, 0.0f, 1.0f, u0, 3, 0);
        OSDPrintUV(99, x - glow_edge, y, glow_edge, height, 0x1000000, &glow_color, 0.0f, u0, u0, u1, 3, 0);
        OSDPrintUV(99, right, y, glow_edge, height, 0x1000000, &glow_color, u1, u0, 1.0f, u1, 3, 0);
        OSDPrintUV(99, x - glow_edge, bottom, glow_edge, glow_edge, 0x1000000, &glow_color, 0.0f, u1, u0, 1.0f, 3, 0);
        OSDPrintUV(99, x, bottom, width, glow_edge, 0x1000000, &glow_color, u0, u1, u1, 1.0f, 3, 0);
        OSDPrintUV(99, right, bottom, glow_edge, glow_edge, 0x1000000, &glow_color, u1, u1, 1.0f, 1.0f, 3, 0);
    }
}

